import java.math.BigDecimal;
import java.math.RoundingMode;

public class InterestCalculator {
    public long monthlyInterest(long balanceInCents, long annualRatePercent) {
        BigDecimal balance = BigDecimal.valueOf(balanceInCents, 2);
