package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class MoneyUtil {

    public static long parseCents(String amount) {
        if (amount == null) throw new IllegalArgumentException("INVALID AMOUNT");
        try {
            BigDecimal val = new BigDecimal(amount.trim());
            if (val.signum() <= 0) throw new IllegalArgumentException("INVALID AMOUNT");
            return val.movePointRight(2).setScale(0, RoundingMode.HALF_UP).longValueExact();
        } catch (NumberFormatException | ArithmeticException e) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
    }

    public static String format(long cents) {
        long abs = Math.abs(cents);
        return (cents < 0 ? "-" : "") + (abs / 100) + "." + String.format("%02d", abs % 100);
    }
}

